-- Read-only catalog snapshot. No application rows or credentials.
-- Scope: migration-owned public/private objects; managed prerequisites are separate.
SELECT jsonb_build_object(
 'schemas',(SELECT COALESCE(jsonb_agg(nspname ORDER BY nspname),'[]') FROM pg_namespace WHERE nspname IN ('public','private')),
 'enums',(SELECT COALESCE(jsonb_agg(x ORDER BY schema,name),'[]') FROM (SELECT n.nspname schema,t.typname name,array_agg(e.enumlabel ORDER BY e.enumsortorder) labels FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname IN ('public','private') GROUP BY n.nspname,t.typname) x),
 'tables',(SELECT COALESCE(jsonb_agg(x ORDER BY schema,name),'[]') FROM (SELECT n.nspname schema,c.relname name,c.relkind kind,c.relrowsecurity rls,c.relforcerowsecurity forced_rls,pg_get_userbyid(c.relowner) owner FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p','v','m')) x),
 'columns',(SELECT COALESCE(jsonb_agg(x ORDER BY schema,table_name,position),'[]') FROM (SELECT n.nspname schema,c.relname table_name,a.attnum position,a.attname name,format_type(a.atttypid,a.atttypmod) type,a.attnotnull not_null,pg_get_expr(d.adbin,d.adrelid) default_expression,a.attidentity identity,a.attgenerated generated FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p','v','m') AND a.attnum>0 AND NOT a.attisdropped) x),
 'constraints',(SELECT COALESCE(jsonb_agg(x ORDER BY schema,table_name,name),'[]') FROM (SELECT n.nspname schema,r.relname table_name,c.conname name,c.contype type,pg_get_constraintdef(c.oid,true) definition,c.convalidated validated FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname IN ('public','private')) x),
 'indexes',(SELECT COALESCE(jsonb_agg(x ORDER BY schemaname,tablename,indexname),'[]') FROM (SELECT schemaname,tablename,indexname,indexdef FROM pg_indexes WHERE schemaname IN ('public','private')) x),
 'policies',(SELECT COALESCE(jsonb_agg(x ORDER BY schemaname,tablename,policyname),'[]') FROM (SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname IN ('public','private')) x),
 'functions',(SELECT COALESCE(jsonb_agg(x ORDER BY schema,name,args),'[]') FROM (SELECT n.nspname schema,p.proname name,pg_get_function_identity_arguments(p.oid) args,p.prosecdef security_definer,p.proconfig settings,pg_get_functiondef(p.oid) definition,pg_get_userbyid(p.proowner) owner,p.proacl::text acl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private') AND p.prokind IN ('f','p')) x),
 'triggers',(SELECT COALESCE(jsonb_agg(x ORDER BY schema,table_name,name),'[]') FROM (SELECT n.nspname schema,c.relname table_name,t.tgname name,pg_get_triggerdef(t.oid,true) definition,t.tgenabled enabled FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname IN ('public','private')) x),
 'relation_grants',(SELECT COALESCE(jsonb_agg(x ORDER BY schema,table_name,grantee,privilege_type),'[]') FROM (SELECT n.nspname schema,c.relname table_name,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END grantee,a.privilege_type,a.is_grantable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p','v','m')) x),
 'column_grants',(SELECT COALESCE(jsonb_agg(x ORDER BY schema,table_name,column_name,grantee,privilege_type),'[]') FROM (SELECT n.nspname schema,c.relname table_name,t.attname column_name,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END grantee,a.privilege_type,a.is_grantable FROM pg_attribute t JOIN pg_class c ON c.oid=t.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(t.attacl) a WHERE n.nspname IN ('public','private') AND t.attnum>0 AND NOT t.attisdropped) x),
 'publication',(SELECT COALESCE(jsonb_agg(x ORDER BY pubname),'[]') FROM (SELECT pubname,puballtables,pubinsert,pubupdate,pubdelete,pubtruncate FROM pg_publication WHERE pubname='supabase_realtime') x)
) AS fingerprint;
